<script setup lang="ts">
import {uiErrorMessage as displayErrorValue} from '../module-localization.ts';

import {localized} from '../module-localization.ts';
import {tr,message as localizedMessage,messageRef} from '../../i18n/index.ts';
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import AppIcon from '../../components/AppIcon.vue';
import {ref,computed,watch,onUnmounted} from 'vue';
import ModuleFrame from '../../components/ModuleFrame.vue';
import ModuleWorkbench from '../../components/ModuleWorkbench.vue';
import ModuleToolbar from '../../components/ModuleToolbar.vue';
import ModuleSection from '../../components/ModuleSection.vue';
import ModuleStatus from '../../components/ModuleStatus.vue';
import ModalDialog from '../../components/ModalDialog.vue';
import SymbolEditor from './SymbolEditor.vue';
import ResultPreview from './ResultPreview.vue';
import type {ResearchContext} from '../../platform/research.ts';
import {projects} from '../../platform/browser.ts';
import {exportFontSnapshot,fontRevision} from '../../state/fonts.ts';
import type {Settings,Preview,Source,Result,Options,Inspection} from './port.ts';
import {clone,swap,defaultOptions} from './state.ts';
const props=defineProps<{context:ResearchContext;stateKey:string;active?:boolean}>();
const emit=defineEmits<{references:[];dirty:[boolean]}>();
const importEpoch=ref(0),step=ref(0),error=messageRef(),message=messageRef(),busy=ref(false),help=ref(false),dirty=ref(false);
const fileInput=ref<HTMLInputElement>(),source=ref<Source>(),preview=ref<Preview>(),settings=ref<Settings>(),result=ref<Result>();
const options=ref<Options>(defaultOptions()),importedOptions=ref<Options>();
const staged=ref<Source>(),inspection=ref<Inspection>(),inspectedSignature=ref('');
const toneDraft=ref<Settings>(),toneDrag=ref<string>(),symbolsDirty=ref(false),symbolEditor=ref<InstanceType<typeof SymbolEditor>>();
const snapshot=ref<{preview:Preview;settings:Settings;signature:string;font:ReturnType<typeof exportFontSnapshot>}>();let controller:AbortController|undefined;
const previewFont=computed(()=>{fontRevision.value;return exportFontSnapshot();});
const port=computed(()=>props.context.files.m14),key='m14:'+props.stateKey;
const saved=projects.read<any>(key,null);
if(['m14-draft/1','m14-draft/2'].includes(saved?.schema)&&saved.source&&saved.preview&&saved.settings){source.value=saved.source;preview.value=saved.preview;settings.value=saved.settings;importedOptions.value=saved.options;toneDraft.value=clone(saved.settings);options.value={...defaultOptions(),...(saved.preview.computation_revision==='m14/2'?saved.options:{})};step.value=saved.preview.computation_revision==='m14/2'?1:0;message.value=saved.preview.computation_revision==='m14/2'?localizedMessage('modules.phonology-induction.text.b01b1912c5f5'):localizedMessage('modules.phonology-induction.text.b589881e915a');}
const legacy=computed(()=>!!preview.value&&preview.value.computation_revision!=='m14/2');
const toneChanged=computed(()=>!!toneDraft.value&&!!settings.value&&(JSON.stringify(toneDraft.value.tone_order)!==JSON.stringify(settings.value.tone_order)||JSON.stringify(toneDraft.value.tone_map)!==JSON.stringify(settings.value.tone_map)));
const editing=computed(()=>toneChanged.value||symbolsDirty.value);
const signature=computed(()=>JSON.stringify([source.value,importedOptions.value,settings.value]));
const stale=computed(()=>!!snapshot.value&&(snapshot.value.signature!==signature.value||editing.value));
const inspectSignature=()=>JSON.stringify([options.value.table_index,options.value.encoding,options.value.delimiter,options.value.start_row]);
const needsRefresh=computed(()=>!!inspection.value&&inspectedSignature.value!==inspectSignature());
const columns=computed(()=>Array.from({length:inspection.value?.column_count??3},(_,i)=>i+1));
const isText=computed(()=>/\.(csv|txt|tsv)$/i.test(staged.value?.name??''));
const mappingError=computed(()=>{if(!inspection.value)return '';const c=options.value.character_column!,i=options.value.ipa_column!,n=options.value.note_column,s=options.value.start_row!;const chosen=[c,i,...(n==null?[]:[n])];if(chosen.some(v=>!Number.isInteger(v)||v<1||v>inspection.value!.column_count)||new Set(chosen).size!==chosen.length)return tr('modules.phonology-induction.text.fe40817c21d6');if(!Number.isInteger(s)||s<1||s>10001)return tr('modules.phonology-induction.text.89a109b8e34a');if(s>inspection.value.total_rows&&inspection.value.sample.every(r=>r.row<s))return tr('modules.phonology-induction.text.109e50bcbe1e');return '';});
watch(()=>dirty.value||busy.value||editing.value||!!staged.value,value=>emit('dirty',value),{flush:'sync'});
onUnmounted(()=>controller?.abort());
function changed(){dirty.value=true;}
async function operation(run:(signal:AbortSignal)=>Promise<void>){if(busy.value)return;error.value='';message.value='';busy.value=true;controller=new AbortController();try{await run(controller.signal);}catch(e){error.value=e instanceof Error?displayErrorValue(e):localizedMessage('modules.phonology-induction.text.825cfa17d9cd');}finally{busy.value=false;controller=undefined;}}
async function selectFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!port.value)return;const opts={...clone(options.value),table_index:0};await operation(async signal=>{const value=await port.value!.inspect(file,opts,signal);if(signal.aborted)return;staged.value=value.source;inspection.value=value.inspection;options.value=opts;const width=value.inspection.column_count;if(options.value.character_column!>width)options.value.character_column=1;if(options.value.ipa_column!>width)options.value.ipa_column=2;if(options.value.note_column!=null&&options.value.note_column>width)options.value.note_column=null;inspectedSignature.value=inspectSignature();step.value=0;message.value=localizedMessage('modules.phonology-induction.text.4e198feff284');});}
async function refreshSample(){if(!staged.value||!port.value)return;const src=clone(staged.value),opts=clone(options.value);await operation(async signal=>{const value=await port.value!.inspectSource(src,opts,signal);if(signal.aborted)return;inspection.value=value;if(options.value.note_column!=null&&options.value.note_column>value.column_count)options.value.note_column=null;inspectedSignature.value=inspectSignature();});}
async function confirmImport(){if(!staged.value||!port.value||mappingError.value||needsRefresh.value)return;const src=clone(staged.value),opts=clone(options.value);opts.skip_first_row=(opts.start_row??2)>1;await operation(async signal=>{const value=await port.value!.analyze(src,opts,signal);if(signal.aborted)return;importEpoch.value++;source.value=src;preview.value=value;settings.value=clone(value.config);toneDraft.value=clone(value.config);importedOptions.value=opts;result.value=undefined;snapshot.value=undefined;staged.value=undefined;symbolsDirty.value=false;step.value=1;changed();message.value=localizedMessage('modules.phonology-induction.text.545e7b7b3c71',{v0:value.diagnostics.accepted_rows});});}
function stageCurrent(){if(!source.value)return;staged.value=clone(source.value);options.value={...defaultOptions(),...clone(importedOptions.value??{}),computation_revision:'m14/2'};void refreshSample();step.value=0;}
function toneValue(){if(!toneDraft.value||!settings.value)return;const cfg=clone(settings.value);cfg.tone_order=clone(toneDraft.value.tone_order);cfg.tone_map=Object.fromEntries(cfg.tone_order.map(t=>[t,toneDraft.value!.tone_map[t].trim()||t]));return cfg;}
function saveTones(){const cfg=toneValue();if(!cfg)return;settings.value=cfg;toneDraft.value=clone(cfg);changed();error.value='';message.value=localizedMessage('modules.phonology-induction.text.3807ffd650e7');step.value=2;}
function saveSymbols(cfg:Settings){if(!settings.value)return;for(const k of ['initial_order','final_order','initial_map','final_map'] as const)Object.assign(settings.value,{[k]:clone(cfg[k])});symbolsDirty.value=false;changed();error.value='';message.value=localizedMessage('modules.phonology-induction.text.42d10c16b7ec');step.value=3;}
function save(){if(busy.value){error.value=localizedMessage('modules.phonology-induction.text.ecfdeea621b7');return false;}if(staged.value){error.value=localizedMessage('modules.phonology-induction.text.4e64a5399543');return false;}if(!source.value||!preview.value||!settings.value){error.value=localizedMessage('modules.phonology-induction.text.422a6c030fec');return false;}if(symbolEditor.value?.pending()){error.value=localizedMessage('modules.phonology-induction.text.b2ebf95a4ad0');return false;}const cfg=toneValue()??clone(settings.value);if(symbolsDirty.value&&symbolEditor.value){const symbols=symbolEditor.value.value();for(const k of ['initial_order','final_order','initial_map','final_map'] as const)Object.assign(cfg,{[k]:clone(symbols[k])});}if(!projects.write(key,{schema:'m14-draft/2',source:source.value,preview:preview.value,settings:cfg,options:importedOptions.value})){error.value=localizedMessage('modules.phonology-induction.text.a5cd3f1bec66');return false;}settings.value=cfg;toneDraft.value=clone(cfg);symbolsDirty.value=false;dirty.value=false;message.value=localizedMessage('modules.phonology-induction.text.cb4c5e37b67f');error.value='';return true;}
defineExpose({save});
function nudgeTone(tone:string,delta:number){if(!toneDraft.value)return;const list=toneDraft.value.tone_order,index=list.indexOf(tone),next=index+delta;if(next>=0&&next<list.length)toneDraft.value.tone_order=swap(list,tone,list[next]);}
function toneCount(tone:string){return preview.value?.analysis.rows.filter(r=>r.tone_value===tone).length??0;}
function toneExamples(tone:string){return preview.value?.analysis.rows.filter(r=>r.tone_value===tone).slice(0,6).map(r=>r.character).join('、')??'';}
async function generate(){if(!port.value||!source.value||!preview.value||!settings.value||!importedOptions.value||editing.value||legacy.value)return;const src=clone(source.value),cfg=clone(settings.value),opts=clone(importedOptions.value),data=clone(preview.value),sig=signature.value,font=exportFontSnapshot();await operation(async signal=>{const value=await port.value!.generate(src,opts,cfg,font,signal);if(signal.aborted)return;result.value=value;snapshot.value={preview:data,settings:cfg,signature:sig,font};step.value=3;message.value=localizedMessage('modules.phonology-induction.text.eb39df1be797');});}
async function saveResults(){if(result.value)await operation(async()=>{message.value=await port.value!.save(result.value!)?localizedMessage('modules.phonology-induction.text.f7a399c93e18'):localizedMessage('modules.phonology-induction.text.44f3cc3f2f84');});}
async function download(id:string){if(result.value)await operation(async()=>{await port.value!.download(result.value!,id);message.value=localizedMessage('modules.phonology-induction.text.596990ad18e9');});}
const names=localized(()=>[tr('modules.phonology-induction.text.576d81bb0631'),tr('modules.phonology-induction.text.548282070827'),tr('modules.phonology-induction.text.be85f991353f'),tr('modules.phonology-induction.text.bb7ef73495dd')]),descriptions=localized(()=>[tr('modules.phonology-induction.text.e04b4b3901de'),tr('modules.phonology-induction.text.364fc7427f03'),tr('modules.phonology-induction.text.21cccd665570'),tr('modules.phonology-induction.text.5986c41ca982')]);
useWebSettings(props.stateKey,{options});
</script>
<template>
