 <template #toolbar><ModuleToolbar><button :disabled="busy||!port" @click="fileInput?.click()">{{tr('modules.phonology-induction.text.d0a55fb01899')}}</button><input ref="fileInput" type="file" accept=".xlsx,.xls,.csv,.txt,.tsv,.docx" hidden @change="selectFile"/><button v-if="busy" @click="controller?.abort()">{{tr('modules.phonology-induction.text.537d17f1c531')}}</button><template #actions><button :disabled="busy||!source" @click="save">{{tr('modules.phonology-induction.text.5329e3f0ee46')}}</button><button @click="help=true">{{tr('modules.phonology-induction.text.a57cfcb8428d')}}</button><button @click="emit('references')"><AppIcon name="book"/>{{tr('modules.phonology-induction.text.7eaa43419522')}}</button></template></ModuleToolbar></template>
