   <ModuleSection v-if="step===0" :title="tr('modules.phonology-induction.text.1a80d4a19269')" :label="tr('modules.phonology-induction.text.1a80d4a19269')">
    <label>{{tr('modules.phonology-induction.text.efc0e7dfec1a')}}<select v-model="options.consonant_only_as_zero_initial" :disabled="busy"><option :value="true">{{tr('modules.phonology-induction.text.7b2240a6d89e')}}</option><option :value="false">{{tr('modules.phonology-induction.text.66d6b752f6f6')}}</option></select></label>
    <p class="hint">{{tr('modules.phonology-induction.text.c857210c7adb')}}</p><p class="hint">{{tr('modules.phonology-induction.text.fea160975d8a')}}</p>
    <template v-if="!staged||isText"><label>{{tr('modules.phonology-induction.text.c1b39f353316')}}<select :aria-label="tr('modules.phonology-induction.text.c1b39f353316')" v-model="options.encoding" :disabled="busy" @change="staged&&refreshSample()"><option value="auto">{{tr('modules.phonology-induction.text.e4f2a44909a7')}}</option><option value="utf-8-sig">UTF-8</option><option value="gb18030">GB18030 / GBK</option><option value="utf-16">UTF-16</option></select></label><label>{{tr('modules.phonology-induction.text.0415f31a96cd')}}<select :aria-label="tr('modules.phonology-induction.text.0415f31a96cd')" v-model="options.delimiter" :disabled="busy" @change="staged&&refreshSample()"><option value="auto">{{tr('modules.phonology-induction.text.1b43fb7df76a')}}</option><option value="tab">{{tr('modules.phonology-induction.text.103180d3f3cb')}}</option><option value="comma">{{tr('modules.phonology-induction.text.c977ef5080c4')}}</option><option value="semicolon">{{tr('modules.phonology-induction.text.de1f33309e58')}}</option><option value="chinese_comma">{{tr('modules.phonology-induction.text.aaf91e401375')}}</option><option value="space">{{tr('modules.phonology-induction.text.bfa4a6e0fe42')}}</option></select></label><p class="hint">{{tr('modules.phonology-induction.text.a199555fb4b8')}}</p></template>
   </ModuleSection>
   <p v-if="editing" class="edit-notice">{{tr('modules.phonology-induction.text.255a58c2aaff')}}</p>
  </template>
  <div v-show="step===0" class="import-step">
