    <template #actions><button :disabled="busy||!port" @click="fileInput?.click()">{{staged?tr('modules.phonology-induction.text.eaa8249ad985'):tr('modules.phonology-induction.text.822fb37dba29')}}</button></template>
    <template v-if="inspection&&staged">
     <div class="file-banner"><strong>{{staged.name}}</strong><span>{{inspection.total_rows}} {{tr('modules.phonology-induction.text.7049a63d1e72')}} {{inspection.column_count}} {{tr('modules.phonology-induction.text.c06d21404eee')}}</span></div>
     <div class="import-fields">
      <label>{{tr('modules.phonology-induction.text.8e2f453f391b')}}<select v-model.number="options.table_index" :disabled="busy" @change="refreshSample"><option v-for="(table,i) in inspection.tables" :key="i" :value="i">{{isText?tr('modules.phonology-induction.text_table'):staged.name.toLowerCase().endsWith('.docx')?tr('modules.phonology-induction.table_number',{number:i+1}):table}}</option></select></label>
      <label>{{tr('modules.phonology-induction.text.610c22bdeb06')}}<input v-model.number="options.start_row" type="number" min="1" max="10001" :aria-label="tr('modules.phonology-induction.text.479e294b963d')" :disabled="busy" @change="refreshSample"/></label>
      <label>{{tr('modules.phonology-induction.text.f3497a72a860')}}<select v-model.number="options.character_column" :disabled="busy" :aria-label="tr('modules.phonology-induction.text.f3497a72a860')"><option v-for="c in columns" :key="c" :value="c">{{tr('modules.phonology-induction.column_number',{number:c})}}</option></select></label>
      <label>{{tr('modules.phonology-induction.text.21607e2321c6')}}<select v-model.number="options.ipa_column" :disabled="busy" :aria-label="tr('modules.phonology-induction.text.21607e2321c6')"><option v-for="c in columns" :key="c" :value="c">{{tr('modules.phonology-induction.column_number',{number:c})}}</option></select></label>
      <label>{{tr('modules.phonology-induction.text.111ce332de8e')}}<select v-model="options.note_column" :disabled="busy" :aria-label="tr('modules.phonology-induction.text.111ce332de8e')"><option :value="null">{{tr('modules.phonology-induction.text.dd21dd9bdd9a')}}</option><option v-for="c in columns" :key="c" :value="c">{{tr('modules.phonology-induction.column_number',{number:c})}}</option></select></label>
     </div>
     <p class="hint">{{tr('modules.phonology-induction.import_row_hint',{skipped:Math.max(0,(options.start_row??2)-1)})}}</p>
     <p v-if="mappingError" role="alert" class="error">{{mappingError}}</p><p v-if="needsRefresh" class="edit-notice">{{tr('modules.phonology-induction.text.005dd90bb8e9')}}</p>
