     <div class="editor-footer"><div><button :disabled="busy" @click="staged=undefined">{{tr('modules.phonology-induction.text.9f5e85764d33')}}</button><button :disabled="busy" @click="refreshSample">{{tr('modules.phonology-induction.text.e772d3fa570e')}}</button></div><button class="primary" :disabled="busy||!!mappingError||needsRefresh" @click="confirmImport">{{tr('modules.phonology-induction.text.fa98e0eb7bc9')}}</button></div>
    </template>
    <div v-else class="import-empty"><span class="table-symbol">▦</span><strong>{{tr('modules.phonology-induction.text.24511a213e20')}}</strong><p>{{tr('modules.phonology-induction.text.7aea88a23c0d')}}</p><span class="format-list">XLSX · XLS · CSV · TSV · TXT · DOCX</span><button class="primary" :disabled="busy||!port" @click="fileInput?.click()">{{tr('modules.phonology-induction.text.822fb37dba29')}}</button></div>
   </ModuleSection>
  </div>
  <template v-if="preview&&settings">
   <ModuleSection v-show="step===1" class="tone-card" :label="tr('modules.phonology-induction.text.03290e5c9278')" :title="tr('modules.phonology-induction.text.03290e5c9278')">
    <template #actions><small>{{toneChanged?tr('modules.phonology-induction.text.2fb2610a0955'):tr('modules.phonology-induction.text.bd03c0aad701')}} · {{settings.tone_order.length}} {{tr('modules.phonology-induction.text.6e9d9212b39b')}}</small></template>
    <p class="hint">{{tr('modules.phonology-induction.text.ba25fc781196')}}</p>
    <div class="tone-scroll"><table v-if="toneDraft" :aria-label="tr('modules.phonology-induction.text.00c3d59f9744')"><thead><tr><th>{{tr('modules.phonology-induction.text.9249ca6c2aab')}}</th><th>{{tr('modules.phonology-induction.text.9c22f7513111')}}</th><th>{{tr('modules.phonology-induction.text.4e05c106b299')}}</th><th>{{tr('modules.phonology-induction.text.f45e5a018256')}}</th><th>{{tr('modules.phonology-induction.text.73e9dea38c59')}}</th></tr></thead><tbody><tr v-for="(tone,i) in toneDraft.tone_order" :key="tone" :draggable="!busy" @dragstart="toneDrag=tone" @dragover.prevent @drop.prevent="!busy&&toneDrag!==undefined&&(toneDraft.tone_order=swap(toneDraft.tone_order,toneDrag,tone))"><td><div class="order-buttons"><span>{{i+1}}</span><button :disabled="busy||i===0" :aria-label="tr('modules.phonology-induction.text.42a833c01dad')+tone" @click="nudgeTone(tone,-1)">↑</button><button :disabled="busy||i+1===toneDraft.tone_order.length" :aria-label="tr('modules.phonology-induction.text.57a86ca3ed3c')+tone" @click="nudgeTone(tone,1)">↓</button></div></td><td>{{tone}}</td><td><input v-model="toneDraft.tone_map[tone]" :disabled="busy" :aria-label="tr('modules.phonology-induction.text.1ab444939c05')+tone" maxlength="100"/></td><td>{{toneCount(tone)}}</td><td>{{toneExamples(tone)}}</td></tr></tbody></table></div>
    <div class="editor-footer"><button :disabled="busy||!toneChanged" @click="toneDraft=clone(settings)">{{tr('modules.phonology-induction.text.03e9e7154094')}}</button><button class="primary" :disabled="busy" @click="saveTones">{{tr('modules.phonology-induction.text.5694ccf79c55')}}</button></div>
   </ModuleSection>
   <SymbolEditor v-show="step===2" ref="symbolEditor" :key="(source?.asset_id??'')+':'+importEpoch" :settings="settings" :preview="preview" :busy="busy" @save="saveSymbols" @dirty="symbolsDirty=$event"/>
   <ResultPreview v-if="step===3" :preview="snapshot?.preview??preview" :settings="snapshot?.settings??settings" :font="snapshot?.font??previewFont" :generated="!!snapshot" :stale="stale"/>
